style.css:
@-moz-document domain("tiktok.com") {
/* Main Background & Entire Page Container */
    html, body, #main-content-wrapper,
    div[class*="DivBodyContainer"],
    div[class*="DivContentContainer"],
    div[class*="DivPageContainer"],
    div[class*="DivFeedContainer"],
    div[class*="DivMainContainer"],
    div[class*="DivContainer"],
    div[class*="DivLayoutContainer"] {
        background-color: #FF0000 !important;
    }

    /* Video Player Outer Container & Black Side Pillarboxes */
    div[class*="DivVideoContainer"],
    div[class*="DivPlayerContainer"],
    div[class*="DivVideoFeedV2Container"],
    div[class*="DivItemContainerV2"],
    div[class*="DivBasicPlayerWrapper"],
    div[class*="DivVideoWrapper"],
    div[class*="DivVideoControlContainer"],
    .video-card-container,
    .xgplayer {
        background-color: #FF0000 !important;
    }

    /* Top Navigation Header Bar */
    header, nav,
    div[class*="DivHeaderContainer"],
    div[class*="DivHeaderWrapper"] {
        background-color: #FF0000 !important;
        border-bottom: 1px solid #FF0000 !important;
    }

    /* Left Sidebar Navigation */
    aside,
    div[class*="DivSideNavContainer"],
    div[class*="DivSidebarContainer"] {
        background-color: #FF0000 !important;
        border-right: 1px solid #FF0000 !important;
    }

    /* Search Bar & Inputs */
    form[role="search"],
    input[type="search"],
    div[class*="DivSearchBoxContainer"] {
        background-color: #FF0000 !important;
        color: #FFFFFF !important;
        border: 1px solid #FF0000 !important;
    }

    /* Comment Section Panels */
    div[class*="DivCommentContainer"],
    div[class*="DivBottomCommentContainer"] {
        background-color: #FF0000 !important;
    }

    /* Buttons */
    button, div[role="button"] {
        background-color: #FF0000 !important;
    }
}
